(() => {
  const state = { user: null, unit: null, units: [], page: 'overview', csrf: '', cache: {} };
  const content = () => document.getElementById('page-content');
  const $ = (s, root=document) => root.querySelector(s);
  const $$ = (s, root=document) => [...root.querySelectorAll(s)];
  const today = () => new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
  const dateBR = v => { if(!v)return '—'; const s=String(v).slice(0,10); const m=s.match(/^(\d{4})-(\d{2})-(\d{2})$/); return m?`${m[3]}/${m[2]}/${m[1]}`:esc(s); };
  const esc = v => String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const brl = cents => { try { const n=Number(cents||0)/100; return n.toLocaleString('pt-BR',{style:'currency',currency:'BRL'}); } catch { return 'R$ 0,00'; } };
  const amountInput = n => n==null?'':(Number(n)/100).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
  const badge = (label,tone='gray') => `<span class="badge ${tone}">${esc(label)}</span>`;
  const empty = (message='Nenhum registro neste período.') => `<div class="empty-state">${esc(message)}</div>`;
  const roleCan = (...roles) => roles.includes(state.user?.role);
  function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;$('#toast-region').append(el);setTimeout(()=>el.remove(),3800);}
  async function getCsrf(){if(state.csrf)return state.csrf;const r=await fetch('/api/auth/csrf');const d=await r.json();state.csrf=d.token;return state.csrf;}
  async function api(url,options={}){
    const method=(options.method||'GET').toUpperCase();const headers=new Headers(options.headers||{});
    if(method!=='GET'&&method!=='HEAD'){headers.set('X-CSRF-Token',await getCsrf());if(!(options.body instanceof FormData))headers.set('Content-Type','application/json');}
    const r=await fetch(url,{...options,headers,credentials:'same-origin'});if(r.status===401){showLogin();throw new Error('Sua sessão expirou. Entre novamente.');}
    const type=r.headers.get('content-type')||'';const data=type.includes('application/json')?await r.json():r;
    if(!r.ok)throw new Error(data.error||'Não foi possível concluir a operação.');return data;
  }
  async function post(url,body){return api(url,{method:'POST',body:JSON.stringify(body)});}
  function showLogin(){state.user=null;document.getElementById('app-shell').hidden=true;document.getElementById('password-change-screen').hidden=true;document.getElementById('login-screen').hidden=false;}
  function showPasswordChange(){document.getElementById('app-shell').hidden=true;document.getElementById('login-screen').hidden=true;document.getElementById('password-change-screen').hidden=false;}
  function showApp(){document.body.classList.toggle('read-only',state.user.role==='auditor');document.body.classList.toggle('operations-user',state.user.role==='operations');document.getElementById('login-screen').hidden=true;document.getElementById('app-shell').hidden=false;$('#profile-name').textContent=state.user.name;$('#profile-role').textContent=state.user.roleLabel;$('#profile-initials').textContent=state.user.name.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();$('#unit-name').textContent=state.unit?.name||'Villa Cruz';$('#today-label').textContent=new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo',weekday:'short',day:'2-digit',month:'short',year:'numeric'}).format(new Date());$$('.admin-nav').forEach(x=>x.classList.toggle('hidden',!roleCan('admin','owner','auditor')));$$('#navigation [data-page="audit"],#navigation [data-page="users"],#navigation [data-page="import"],#navigation [data-page="settings"]').forEach(x=>x.classList.toggle('hidden',x.dataset.page==='audit'?!roleCan('admin','owner','auditor'):x.dataset.page==='users'?!roleCan('admin'):x.dataset.page==='import'?!roleCan('admin','owner','finance'):!roleCan('admin','owner')));$$('#navigation [data-page="expenses"],#navigation [data-page="dre"],#navigation [data-page="reports"]').forEach(x=>x.classList.toggle('hidden',state.user.role==='operations'));}
  function heading(title,desc,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${desc}</p></div><div class="heading-actions">${actions}</div></div>`;}
  function card(title,contentHtml,tools=''){return `<section class="card section-card"><div class="section-head"><div><h2>${title}</h2></div>${tools}</div>${contentHtml}</section>`;}
  function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows||''}</tbody></table></div>`;}
  function rowEmpty(cols,msg){return `<tr><td colspan="${cols}" class="empty-state">${esc(msg)}</td></tr>`;}
  function selectOptions(categories,kind,selected=''){const list=categories.filter(c=>c.kind===kind);return `<option value="">Sem classificação</option>`+list.map(c=>`<option value="${esc(c.id)}" ${selected===c.id?'selected':''}>${esc(c.name)}</option>`).join('');}
  async function categories(){return api(`/api/categories?unit_id=${encodeURIComponent(state.unit.id)}`);}
  function setPage(page){state.page=page;state.cache={};$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#sidebar').classList.remove('open');render();}
  function loading(){content().innerHTML='<div class="loading-state"><span class="spinner"></span>Carregando...</div>';}

  async function render(){if(!state.user)return;loading();$('#breadcrumb').textContent=({overview:'Visão geral',sales:'Faturamento e CMV',inventory:'Estoque',expenses:'Despesas e notas',cash:'Caixa da loja',dre:'DRE',reports:'Relatórios',import:'Importar Excel',audit:'Auditoria',users:'Usuários',settings:'Metas e categorias'})[state.page]||'Visão geral';try{await ({overview:renderOverview,sales:renderSales,inventory:renderInventory,expenses:renderExpenses,cash:renderCash,dre:renderDre,reports:renderReports,import:renderImport,audit:renderAudit,users:renderUsers,settings:renderSettings})[state.page]();}catch(e){if(state.user)content().innerHTML=`<div class="alert-panel red">${esc(e.message)}</div>`;}}

  async function renderOverview(){
    const from=today(),[d,cash]=await Promise.all([api(`/api/dashboard?unit_id=${state.unit.id}&from=${from}&to=${from}`),api(`/api/cash?unit_id=${state.unit.id}`)]);
    const sale=BigInt(d.sales.amount||0),target=BigInt(d.sales.target||0),pct=target?Number(sale*10000n/target)/100:0;
    const alerts=[];
    const alert=(page,title,detail,count,tone='amber')=>`<button class="alert-row actionable-alert" data-page-link="${page}"><span class="alert-mark ${tone==='red'?'red':''}"></span><span class="alert-copy"><strong>${title}</strong><small>${detail}</small></span>${count!==null?`<span class="alert-count">${count}</span>`:'<span class="alert-arrow" aria-hidden="true">→</span>'}</button>`;
    if(!Number(d.sales.days))alerts.push(alert('sales','Faturamento de hoje não lançado','Confira se o movimento do dia já foi registrado.',null,'amber'));
    if(d.finance_visible&&cash.open_session)alerts.push(alert('cash','Caixa aberto',`Turno ${esc(cash.open_session.shift_name)} · confira movimentos e fechamento.`,null,'amber'));
    if(d.finance_visible&&d.due&&Number(d.due.overdue))alerts.push(alert('expenses','Contas vencidas','Abra as despesas para conferir vencimentos e pagamentos.',d.due.overdue,'red'));
    if(d.finance_visible&&d.due&&Number(d.due.due_soon))alerts.push(alert('expenses','Vencimentos próximos','Contas com vencimento nos próximos 7 dias.',d.due.due_soon,'amber'));
    if(Number(d.stock.expired))alerts.push(alert('inventory','Lotes vencidos','Confira os lotes e registre a destinação.',d.stock.expired,'red'));
    if(Number(d.stock.expires_soon))alerts.push(alert('inventory','Validades próximas','Lotes vencem em até 7 dias; priorize a conferência.',d.stock.expires_soon,'amber'));
    if(Number(d.stock.low_stock))alerts.push(alert('inventory','Estoque baixo','Produtos no mínimo ou abaixo do mínimo.',d.stock.low_stock,'amber'));
    if(!cash.open_session&&roleCan('admin','owner','finance'))alerts.push(alert('cash','Caixa fechado','Acesse para abrir o caixa do turno, se necessário.',null,'amber'));
    if(!alerts.length)alerts.push(`<div class="alert-row"><span class="alert-mark green"></span><span class="alert-copy"><strong>Sem pendências identificadas</strong><small>Os alertas são calculados com os registros atuais do sistema.</small></span></div>`);
    const recent=(d.activity||[]).map(a=>`<tr><td>${esc(a.action)}</td><td>${esc(a.entity_type)}</td><td>${new Date(a.created_at).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'})}</td></tr>`).join('')||rowEmpty(3,'Ainda não há atividade registrada.');
    const quickActions=`${roleCan('admin','owner','finance','operations')?'<button class="button secondary" data-action="go-sales">+ Lançar faturamento</button>':''}${roleCan('admin','owner','finance')?'<button class="button primary" data-action="go-expenses">+ Registrar despesa</button>':''}`;
    const importAction=roleCan('admin','owner','finance')?'<button class="button secondary" data-page-link="import">⇧ Importar planilha</button>':'';
    content().innerHTML=`${heading(`Olá, ${esc(state.user.name.split(' ')[0])}`,`Resumo operacional de hoje · ${dateBR(from)}`,quickActions)}
      <div class="quick-actions"><button class="button secondary" data-page-link="inventory">＋ Receber estoque</button><button class="button secondary" data-page-link="cash">＋ Movimentar caixa</button>${importAction}</div>
      <div class="grid kpi-grid">
        <article class="card kpi-card"><div class="kpi-top">Faturamento hoje <span class="kpi-icon">↗</span></div><div class="kpi-value">${brl(d.sales.amount)}</div><div class="kpi-foot">${d.sales.days} lançamento(s) no período</div></article>
        <article class="card kpi-card"><div class="kpi-top">Meta atingida <span class="kpi-icon">◎</span></div><div class="kpi-value">${target?pct.toLocaleString('pt-BR',{maximumFractionDigits:1})+'%':'—'}</div><div class="kpi-foot">${target?`Meta registrada: ${brl(d.sales.target)}`:'Cadastre uma meta para o período'}</div></article>
        ${d.finance_visible?`<article class="card kpi-card"><div class="kpi-top">Saldo do caixa reservado <span class="kpi-icon">◫</span></div><div class="kpi-value">${brl(d.cash_cents)}</div><div class="kpi-foot">Livro de movimentos da unidade</div></article><article class="card kpi-card"><div class="kpi-top">Contas em aberto <span class="kpi-icon">▧</span></div><div class="kpi-value">${brl(d.payables_cents)}</div><div class="kpi-foot">${d.due.overdue} vencida(s) · ${d.due.due_soon} próxima(s)</div></article>`:''}
      </div>
      <div class="grid overview-grid"><div>${card('Ações do dia',`<div class="alert-list">${alerts.join('')}</div>`,d.finance_visible?'<button class="text-link" data-page-link="expenses">Ver despesas</button>':'')}
        ${d.finance_visible?`<div class="card section-card spaced-top"><div class="section-head"><div><h2>Resultado de hoje</h2><p>Período aberto · valores do dia</p></div><button class="text-link" data-page-link="dre">Abrir DRE</button></div><div class="help-text">A DRE por competência está disponível em Gestão. O CMV depende da regra de cálculo confirmada pela Villa Cruz; compras, consumo e cortesias são mantidos separados.</div></div>`:''}</div>
        <div>${card('Atividade recente',table(['Ação','Registro','Data'],recent),'<span class="badge gray">Auditoria</span>')}</div>
      </div>`;
  }

  async function renderSales(){const [rows,cats]=await Promise.all([api(`/api/sales?unit_id=${state.unit.id}`),categories()]);const sales=rows.map(r=>`<tr><td>${dateBR(r.sale_date)}</td><td>${esc(r.channel)}</td><td class="money">${brl(r.amount_cents)}</td><td>${r.target_cents?brl(r.target_cents):'—'}</td><td>${badge(r.status==='confirmed'?'Confirmado':r.status,'green')}</td><td>${esc(r.notes||'—')}${(r.attachments||[]).map(a=>`<br><a class="file-link" target="_blank" rel="noopener noreferrer" href="/api/attachments/${encodeURIComponent(a.id)}?unit_id=${encodeURIComponent(state.unit.id)}">▧ ${esc(a.name)}</a>`).join('')}</td></tr>`).join('')||rowEmpty(6,'Nenhum faturamento registrado.');content().innerHTML=`${heading('Faturamento e CMV','Lance o faturamento por dia e mantenha compras, consumo e cortesias separados.')}<div class="alert-panel">A meta de compras padrão pode ser configurada por vigência. O cálculo oficial do CMV está pendente de validação; o sistema não soma compras, consumo e cortesias automaticamente.</div><section class="card form-card"><h2>Novo lançamento diário</h2><form id="sale-form" class="form-grid"><label>Data<input name="sale_date" type="date" value="${today()}" required></label><label>Canal<select name="channel"><option>Salão</option><option>Delivery</option><option>iFood</option><option>Retirada</option><option>Outro</option></select></label><label>Faturamento (R$)<input name="amount" inputmode="decimal" placeholder="0,00" required></label><label>Meta do dia (R$)<input name="target" inputmode="decimal" placeholder="Opcional"></label><label class="form-span-2">Observações<input name="notes" maxlength="2000" placeholder="Informações do dia"></label><label class="form-span-2">Comprovante opcional<input name="attachment" type="file" accept=".pdf,.png,.jpg,.jpeg"><span class="hint">PDF, JPG ou PNG · até 10 MB</span></label><div class="form-actions"><button class="button primary">Salvar faturamento</button></div></form></section><section class="card table-card"><div class="table-toolbar"><h2>Lançamentos recentes</h2><div class="toolbar-actions"><input id="sales-search" class="period-control" placeholder="Buscar canal..."></div></div>${table(['Data','Canal','Faturamento','Meta','Status','Observações'],sales)}</section>`;$('#sales-search').addEventListener('input',e=>filterTable(e.target.value));}

  async function renderInventory(){const [products,movements]=await Promise.all([api(`/api/products?unit_id=${state.unit.id}`),api(`/api/stock/movements?unit_id=${state.unit.id}`)]);const rows=products.map(p=>`<tr><td><strong>${esc(p.name)}</strong><div class="muted">${esc(p.sku||'Sem SKU')}</div></td><td>${esc(p.base_unit)}</td><td class="money">${Number(p.stock_quantity).toLocaleString('pt-BR',{maximumFractionDigits:3})}</td><td>${Number(p.stock_quantity)<=Number(p.minimum_quantity)?badge('Estoque baixo','amber'):badge('Disponível','green')}</td><td>${dateBR(p.nearest_expiry)}</td><td><button class="button secondary small" data-action="view-lots" data-id="${esc(p.id)}" data-name="${esc(p.name)}">Ver lotes</button> <button class="button secondary small" data-action="receive-product" data-id="${esc(p.id)}" data-name="${esc(p.name)}">Receber lote</button> <button class="button secondary small" data-action="move-product" data-id="${esc(p.id)}" data-name="${esc(p.name)}">Registrar saída</button></td></tr>`).join('')||rowEmpty(6,'Cadastre o primeiro produto para controlar os lotes.');const moves=movements.slice(0,8).map(m=>`<tr><td>${new Date(m.created_at).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'})}</td><td>${esc(m.product_name)}</td><td>${esc(m.movement_type)}</td><td>${Number(m.quantity).toLocaleString('pt-BR')}</td><td>${esc(m.reason||'—')}</td></tr>`).join('')||rowEmpty(5,'Sem movimentações de estoque.');content().innerHTML=`${heading('Estoque','Produtos, lotes, validade e movimentações com trilha de responsável.',`<button class="button primary" data-action="new-product">＋ Novo produto</button>`)}<div class="mini-kpis"><div class="mini-kpi">Produtos <strong>${products.length}</strong></div><div class="mini-kpi">Lotes com vencimento próximo <strong>${products.filter(p=>p.nearest_expiry&&p.nearest_expiry<=new Date(Date.now()+7*86400000).toISOString().slice(0,10)).length}</strong></div></div><section class="card table-card" style="margin-top:14px"><div class="table-toolbar"><h2>Produtos e saldo</h2><span class="badge gray">FEFO: primeiro a vencer</span></div>${table(['Produto','Unidade','Saldo','Situação','Próxima validade','Ações'],rows)}</section><div style="height:14px"></div><section class="card table-card"><div class="table-toolbar"><h2>Movimentações recentes</h2></div>${table(['Data','Produto','Tipo','Quantidade','Motivo'],moves)}</section><p class="help-text">O sistema sugere consumo FEFO e impede saídas acima do saldo registrado. Lotes sem validade ficam identificados como sem validade; não são presumidos válidos.</p>`;}

  async function renderExpenses(){
    const [rows,cats]=await Promise.all([api(`/api/expenses?unit_id=${state.unit.id}`),categories()]);
    const outstanding=r=>{const remaining=BigInt(r.total_cents||0)-BigInt(r.paid_cents||0);return remaining>0n?remaining:0n;};
    const active=rows.filter(r=>!['Paga','Cancelada'].includes(r.derived_status));
    const overdue=active.filter(r=>r.derived_status==='Vencida'),soon=active.filter(r=>r.derived_status==='Vence em breve');
    const openTotal=active.reduce((sum,r)=>sum+outstanding(r),0n);
    const list=rows.map(r=>{
      const canPay=!['Paga','Cancelada'].includes(r.derived_status);
      const action=canPay?`<button class="button secondary small" data-action="pay-expense" data-id="${esc(r.id)}" data-supplier="${esc(r.supplier)}" data-total="${esc(r.total_cents)}" data-count="${esc(r.installment_count)}">Registrar pagamento</button>`:badge(r.derived_status==='Paga'?'Quitada':'Cancelada',r.derived_status==='Paga'?'green':'gray');
      return `<tr><td><strong>${esc(r.supplier)}</strong><div class="muted">${esc(r.document_number||r.description)}</div>${(r.attachments||[]).map(a=>`<a class="file-link" target="_blank" rel="noopener noreferrer" href="/api/attachments/${encodeURIComponent(a.id)}?unit_id=${encodeURIComponent(state.unit.id)}">▧ ${esc(a.name)}</a>`).join('<br>')}</td><td>${esc(r.category_name||'Sem classificação')}</td><td>${dateBR(r.issue_date)}</td><td>${dateBR(r.due_date)}</td><td class="money">${brl(r.total_cents)}</td><td class="money">${brl(outstanding(r).toString())}</td><td data-status="${esc(r.derived_status)}">${badge(r.derived_status,r.derived_status==='Vencida'?'red':r.derived_status==='Vence em breve'?'amber':r.derived_status==='Paga'?'green':'gray')}</td><td>${action}</td></tr>`;
    }).join('')||rowEmpty(8,'Nenhuma despesa cadastrada.');
    const summary=`<div class="mini-kpis due-summary"><div class="mini-kpi">Saldo em aberto <strong>${brl(openTotal.toString())}</strong></div><div class="mini-kpi">Vencidas <strong>${overdue.length}</strong></div><div class="mini-kpi">Vencem em até 7 dias <strong>${soon.length}</strong></div></div>`;
    content().innerHTML=`${heading('Despesas e notas','Contas a pagar, vencimentos, classificação e vínculo com os pagamentos do caixa.')}${summary}<section class="card form-card"><h2>Registrar despesa ou nota</h2><form id="expense-form" class="form-grid"><label>Fornecedor<input name="supplier" maxlength="160" required></label><label>Nº documento<input name="document_number" maxlength="120" placeholder="Opcional"></label><label>Emissão<input name="issue_date" type="date" value="${today()}" required></label><label>Competência<input name="accrual_date" type="date" value="${today()}" required></label><label>Vencimento<input name="due_date" type="date"></label><label>Valor total (R$)<input name="total" inputmode="decimal" required></label><label>Parcelas<input name="installment_count" type="number" min="1" max="120" value="1"></label><label>Categoria DRE<select name="category_id">${selectOptions(cats,'expense')}</select></label><label class="form-span-2">Descrição<input name="description" maxlength="250" required></label><label>Forma de pagamento<select name="payment_method"><option value="">A definir</option><option>Dinheiro</option><option>Pix</option><option>Débito</option><option>Crédito</option><option>Boleto</option><option>Transferência</option></select></label><label>Natureza<input name="nature" placeholder="Ex.: insumo, manutenção"></label><label class="form-span-2">Observações<input name="notes" maxlength="2000"></label><label class="form-span-2">Nota ou comprovante<input name="attachment" type="file" accept=".pdf,.png,.jpg,.jpeg"><span class="hint">PDF, JPG ou PNG · até 10 MB</span></label><div class="form-actions"><button class="button primary">Salvar despesa</button></div></form></section><section class="card table-card"><div class="table-toolbar"><h2>Contas e notas</h2><div class="filter-row"><select id="expense-filter"><option value="">Todos os status</option><option>Vencida</option><option>Vence em breve</option><option>Em aberto</option><option>Paga</option></select></div></div>${table(['Fornecedor / documento','Categoria','Emissão','Vencimento','Valor total','Saldo aberto','Status','Ação'],list)}</section>`;
    $('#expense-filter').addEventListener('change',e=>filterStatus(e.target.value));
  }

  async function renderCash(){const c=await api(`/api/cash?unit_id=${state.unit.id}`);const movements=c.movements.map(m=>`<tr><td>${new Date(m.occurred_at).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'})}</td><td>${esc(m.category)}</td><td>${esc(m.description)}</td><td>${esc(m.responsible||'—')}</td><td class="money ${m.movement_type==='outflow'?'negative':''}">${m.movement_type==='outflow'?'−':'+'}${brl(m.amount_cents)}</td></tr>`).join('')||rowEmpty(5,'Nenhum movimento registrado.');const session=c.open_session;const sessionPanel=session?`<div class="alert-panel green">Caixa aberto: <strong>${esc(session.shift_name)}</strong> desde ${new Date(session.opened_at).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'})} · saldo calculado geral ${brl(c.balance_cents)}.</div><div class="grid" style="grid-template-columns:1fr 1fr;gap:14px"><section class="card form-card"><h2>Movimentar caixa</h2><form id="cash-movement-form" class="form-grid"><label>Tipo<select name="movement_type"><option value="inflow">Entrada</option><option value="outflow">Saída</option></select></label><label>Valor (R$)<input name="amount" inputmode="decimal" required></label><label>Categoria<input name="category" required placeholder="Ex.: suprimento"></label><label>Responsável<input name="responsible" required value="${esc(state.user.name)}"></label><label class="form-span-2">Descrição<input name="description" required maxlength="250"></label><label>Forma de pagamento<input name="payment_method"></label><label>Observações<input name="notes" maxlength="1000"></label><div class="form-actions"><button class="button primary">Registrar movimento</button></div></form></section><section class="card form-card"><h2>Fechar caixa</h2><p class="help-text">Saldo calculado no turno: <strong>${brl(session.expected_cents||0)}</strong>. Informe o valor contado; diferenças exigem justificativa.</p><form id="cash-close-form" class="form-grid"><label class="form-span-2">Valor contado (R$)<input name="counted_amount" inputmode="decimal" required></label><label class="form-span-2">Justificativa da diferença<input name="reason" maxlength="300" placeholder="Obrigatória se houver diferença"></label><div class="form-actions"><button class="button primary">Conferir e fechar</button></div></form></section></div>`:`<div class="grid overview-grid"><section class="card form-card"><h2>Abrir caixa do turno</h2><form id="cash-open-form" class="form-grid"><label>Turno<input name="shift_name" required placeholder="Ex.: almoço"></label><label>Saldo inicial (R$)<input name="opening_amount" inputmode="decimal" value="0,00" required></label><div class="form-actions"><button class="button primary">Abrir caixa</button></div></form></section><section class="card section-card"><h2>Saldo do caixa reservado</h2><div class="kpi-value">${brl(c.balance_cents)}</div><p class="help-text">Saldo acumulado do livro de movimentos. Aberturas e fechamentos de turno ficam registrados separadamente.</p></section></div>`;content().innerHTML=`${heading('Caixa da loja','Abertura, entradas, saídas e fechamento conferido por turno.',`<span class="badge ${session?'green':'amber'}">${session?'Caixa aberto':'Caixa fechado'}</span>`)}${sessionPanel}<section class="card table-card"><div class="table-toolbar"><h2>Livro de movimentos</h2><a class="button secondary small" href="/api/reports/cash.csv?unit_id=${state.unit.id}">Exportar caixa CSV</a></div>${table(['Data','Categoria','Descrição','Responsável','Valor'],movements)}</section>`;}

  async function renderDre(){const month=new Date().toLocaleDateString('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit'});const d=await api(`/api/dre?unit_id=${state.unit.id}&month=${month}`);const labels={deduction:'Deduções',cmv:'CMV',personnel:'Pessoal',operating:'Operacionais',administrative:'Administrativas',occupancy:'Ocupação',financial:'Financeiras',other:'Outras despesas',unclassified:'Sem classificação'};const rows=Object.entries(d.expense_groups).map(([g,v])=>`<div class="dre-group"><span>${esc(labels[g]||g)} ${g==='cmv'?'<span class="badge amber">regra pendente</span>':''}</span><strong>${brl(v)}</strong><span class="muted">${d.gross_revenue_cents!=='0'?`${(Number(v)/Number(d.gross_revenue_cents)*100).toLocaleString('pt-BR',{maximumFractionDigits:1})}% da receita`:''}</span></div>`).join('');content().innerHTML=`${heading('DRE gerencial','Apuração por competência, com pagamento de caixa fora da soma de despesas.',`<label class="period-control">Competência <input id="dre-month" type="month" value="${month}" style="border:0;background:transparent"></label>`)}<div class="alert-panel">${esc(d.methodology)} O período está aberto; valores podem mudar conforme novos lançamentos.</div><section class="card section-card"><div class="section-head"><div><h2>Demonstrativo · ${esc(month)}</h2><p>${dateBR(d.period.start)} a ${dateBR(d.period.end)} · Período aberto</p></div>${d.classified?badge('Classificado','green'):badge('Há lançamentos sem classificação','amber')}</div><div class="dre-group"><span>Receita bruta</span><strong>${brl(d.gross_revenue_cents)}</strong><span>100%</span></div><div class="dre-group dre-sub"><span>(−) Deduções e taxas</span><strong>${brl(d.deductions_cents)}</strong><span>${d.gross_revenue_cents!=='0'?(Number(d.deductions_cents)/Number(d.gross_revenue_cents)*100).toLocaleString('pt-BR',{maximumFractionDigits:1})+'%':''}</span></div><div class="dre-group dre-total"><span>Receita líquida</span><strong>${brl(d.net_revenue_cents)}</strong><span></span></div>${rows}<div class="dre-group dre-total"><span>Resultado após despesas classificadas</span><strong>${brl(d.operating_result_cents)}</strong><span></span></div><p class="help-text">Fórmula atual: faturamento confirmado − deduções − despesas por competência. O CMV oficial requer validação das regras da Villa Cruz. Clique nas categorias em Relatórios para abrir os registros de origem.</p></section>`;$('#dre-month').addEventListener('change',renderDre);}

  async function renderReports(){
    const reports=await api(`/api/reports/saved?unit_id=${state.unit.id}`);
    const rows=reports.map(r=>`<tr><td><strong>${esc(r.name)}</strong><div class="muted">${esc(JSON.stringify(r.filters))}</div></td><td>${esc(r.report_type)}</td><td>${dateBR(r.created_at)}</td><td>${esc(r.owner_id===state.user.id?'Meu relatório':'Compartilhado')}</td><td><button class="button secondary small" data-run-saved-report="${esc(r.id)}">Executar</button></td></tr>`).join('')||rowEmpty(5,'Você ainda não salvou um relatório.');
    content().innerHTML=`${heading('Relatórios gerenciais','Execute consultas com filtros reproduzíveis e exporte o mesmo resultado.')}<section class="card form-card"><h2>Executar ou salvar consulta</h2><form id="saved-report-form" class="form-grid"><label>Nome da consulta<input name="name" maxlength="100" placeholder="Ex.: despesas de insumos do mês"></label><label>Fonte<select name="report_type"><option value="sales">Faturamento</option><option value="expenses">Despesas por competência</option><option value="cash">Movimentos de caixa</option><option value="cash_closings">Fechamentos de caixa</option><option value="stock">Posição por lote</option><option value="stock_moves">Movimentações de estoque</option><option value="dre">DRE · lançamentos de origem</option></select></label><label>De<input name="from" type="date"></label><label>Até<input name="to" type="date"></label><label>Status<select name="status"><option value="">Todos</option><option value="confirmed">Confirmado</option><option value="draft">Rascunho</option><option value="open">Em aberto</option><option value="paid">Pago</option><option value="review">Em revisão</option><option value="inflow">Entrada</option><option value="outflow">Saída</option><option value="reversal">Reversão</option><option value="inbound">Recebimento</option><option value="waste">Perda</option><option value="courtesy">Cortesia</option><option value="consumption">Consumo</option><option value="adjustment">Ajuste</option></select></label><label class="form-span-2">Busca<input name="search" maxlength="120" placeholder="Produto, fornecedor, descrição, canal ou categoria"></label><div class="form-actions"><button class="button primary" type="button" data-run-report>Executar relatório</button><button class="button secondary" type="submit">Salvar configuração</button></div></form></section><div id="report-result"></div><section class="card table-card"><div class="table-toolbar"><h2>Consultas salvas</h2></div>${table(['Nome e filtros','Fonte','Criado em','Acesso',''],rows)}</section><p class="help-text">Consultas mostram até 5.000 registros por execução. DRE é uma visão gerencial de faturamento e despesas por competência; CMV ainda depende de regra validada.</p>`;
  }
  async function executeReport(type,filters={}){
    const params=new URLSearchParams({unit_id:state.unit.id,type,...Object.fromEntries(Object.entries(filters).filter(([,v])=>v))});
    const result=await api(`/api/reports/run?${params}`);
    const labels={data:'Data',canal:'Canal',valor_centavos:'Valor',meta_centavos:'Meta',status:'Status',observacoes:'Observações',fornecedor:'Fornecedor',documento:'Documento',competencia:'Competência',vencimento:'Vencimento',descricao:'Descrição',categoria:'Categoria',turno:'Turno',tipo:'Tipo',responsavel:'Responsável',forma_pagamento:'Forma de pagamento',aberto_em:'Abertura',aberto_por:'Aberto por',fechado_em:'Fechamento',fechado_por:'Fechado por',esperado_centavos:'Esperado',contado_centavos:'Contado',diferenca_centavos:'Diferença',justificativa:'Justificativa',produto:'Produto',sku:'SKU',unidade:'Unidade',minimo:'Mínimo',lote:'Lote',recebido:'Recebido',validade:'Validade',saldo:'Saldo',custo_unitario_centavos:'Custo unitário',origem:'Origem',grupo:'Grupo',quantidade:'Quantidade',motivo:'Motivo',referencia:'Referência'};
    const head=result.columns.map(c=>`<th>${esc(labels[c]||c.replaceAll('_',' '))}</th>`).join('');
    const rows=result.rows.map(row=>`<tr>${result.columns.map(c=>`<td>${esc(c.endsWith('_centavos')?brl(row[c]):row[c]??'—')}</td>`).join('')}</tr>`).join('')||rowEmpty(result.columns.length,'Nenhum registro corresponde aos filtros.');
    const exportHref=`/api/reports/run.csv?${params}`;
    $('#report-result').innerHTML=`<section class="card table-card"><div class="table-toolbar"><div><h2>${esc(result.title)}</h2><p>${result.rows.length} registro(s) · Filtros: ${esc(JSON.stringify(result.filters))}</p></div><a class="button secondary small" href="${exportHref}">Exportar CSV</a></div>${result.limited?'<div class="alert-panel">Exibindo os primeiros 5.000 registros; refine os filtros para exportar um período menor.</div>':''}<div class="table-scroll"><table><thead><tr>${head}</tr></thead><tbody>${rows}</tbody></table></div></section>`;
  }  async function renderImport(){content().innerHTML=`${heading('Importar planilhas','Pré-visualize uma aba Excel, mapeie colunas e confira erros antes de gravar.') }<div class="alert-panel">O original não é alterado. Esta versão importa uma aba de cada vez para faturamento, despesas ou produtos. Valores sem leitura válida são rejeitados e listados no relatório.</div><section class="card form-card"><h2>1 · Selecionar planilha e tipo de dados</h2><form id="import-form" class="form-grid"><label>Tipo<select name="import_type"><option value="sales">Faturamento diário</option><option value="expenses">Despesas/notas</option><option value="products">Produtos</option></select></label><label>Nome da aba (opcional)<input name="sheet_name" placeholder="Usa a primeira aba se vazio"></label><label class="form-span-2">Arquivo XLSX<input name="file" type="file" accept=".xlsx" required></label><div class="form-actions"><button class="button primary">Ler e pré-visualizar</button></div></form></section><div id="import-preview"></div>`;}

  async function renderAudit(){const rows=await api(`/api/audit?unit_id=${state.unit.id}`);const html=rows.map(r=>`<tr><td>${new Date(r.created_at).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'})}</td><td>${esc(r.user_name||'Sistema')}</td><td>${esc(r.action)}</td><td>${esc(r.entity_type)} <span class="muted">${esc(r.entity_id||'')}</span></td><td>${esc(r.reason||'—')}</td></tr>`).join('')||rowEmpty(5,'Nenhum evento registrado.');content().innerHTML=`${heading('Auditoria','Histórico de operações financeiras, alterações e documentos acessados.') }<div class="alert-panel">A trilha registra quem fez, quando, tipo de ação e dados anteriores/novos. O acesso a detalhes respeita o perfil autorizado.</div><section class="card table-card"><div class="table-toolbar"><h2>Eventos recentes</h2><span class="badge gray">Últimos 300 eventos</span></div>${table(['Data e hora','Usuário','Ação','Registro','Justificativa'],html)}</section>`;}

  async function renderUsers(){const users=await api(`/api/admin/users?unit_id=${state.unit.id}`);const rows=users.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td>${esc(({admin:'Administrador',owner:'Proprietário/Gestor',finance:'Financeiro',operations:'Operação',auditor:'Consulta/Auditoria'})[u.role])}</td><td>${badge(u.active?'Ativo':'Inativo',u.active?'green':'gray')}</td><td>${u.must_change_password?badge('Troca pendente','amber'):badge('Atualizada','green')}</td></tr>`).join('')||rowEmpty(5,'Sem usuários.');content().innerHTML=`${heading('Usuários e acessos','Cadastre pessoas com o menor nível de acesso necessário.') }<section class="card form-card"><h2>Novo usuário</h2><form id="user-form" class="form-grid"><label>Nome<input name="name" required></label><label>E-mail<input name="email" type="email" required></label><label>Perfil<select name="role"><option value="finance">Financeiro</option><option value="operations">Operação</option><option value="owner">Proprietário/Gestor</option><option value="auditor">Consulta/Auditoria</option><option value="admin">Administrador</option></select></label><label>Senha temporária<span class="hint">mínimo 8 caracteres; troca obrigatória no primeiro acesso</span><input name="password" type="password" minlength="8" maxlength="72" autocomplete="new-password" required></label><div class="form-actions"><button class="button primary">Criar acesso</button></div></form></section><section class="card table-card"><div class="table-toolbar"><h2>Usuários da unidade</h2></div>${table(['Nome','E-mail','Perfil','Status','Senha'],rows)}</section><p class="help-text">MFA e recuperação de senha ainda não estão disponíveis. Entregue a senha temporária por um canal privado e oriente cada pessoa a trocá-la ao entrar.</p>`;}

  async function renderSettings(){const [cats,settings]=await Promise.all([categories(),api(`/api/settings?unit_id=${state.unit.id}`)]);const current=settings.purchase_target_percent?.value;const rows=cats.map(c=>`<tr><td>${esc(c.name)}</td><td>${esc(c.kind)}</td><td>${esc(c.dre_group||'Não aplicável')}</td></tr>`).join('')||rowEmpty(3,'Sem categorias.');content().innerHTML=`${heading('Metas e categorias','Defina parâmetros por vigência e a classificação usada pela DRE.') }<div class="grid overview-grid"><section class="card form-card"><h2>Meta de compras sobre faturamento</h2><form id="target-form" class="form-grid"><label>Meta (%)<input name="purchase_target_percent" inputmode="decimal" value="${current??36}" required></label><label>Vigência a partir de<input name="effective_from" type="date" value="${settings.purchase_target_percent?.effective_from||today()}" required></label><div class="form-actions"><button class="button primary">Salvar nova vigência</button></div></form><p class="help-text">O valor inicial de 36% é apenas uma referência configurável. A meta não calcula o CMV automaticamente.</p></section><section class="card form-card"><h2>Nova categoria</h2><form id="category-form" class="form-grid"><label>Nome<input name="name" required></label><label>Tipo<select name="kind"><option value="expense">Despesa</option><option value="income">Receita</option><option value="stock">Estoque</option></select></label><label>Grupo da DRE<select name="dre_group"><option value="">Sem grupo</option><option value="deduction">Deduções</option><option value="cmv">CMV</option><option value="personnel">Pessoal</option><option value="operating">Operacional</option><option value="administrative">Administrativa</option><option value="occupancy">Ocupação</option><option value="financial">Financeira</option><option value="other">Outras</option></select></label><div class="form-actions"><button class="button primary">Adicionar categoria</button></div></form></section></div><section class="card table-card"><div class="table-toolbar"><h2>Categorias da unidade</h2></div>${table(['Categoria','Tipo','Grupo da DRE'],rows)}</section>`;}

  function filterTable(term){const t=term.toLowerCase();$$('#page-content tbody tr').forEach(r=>r.classList.toggle('hidden',!r.textContent.toLowerCase().includes(t)));}
  function filterStatus(status){$$('#page-content tbody tr').forEach(r=>r.classList.toggle('hidden',!!status&&!r.querySelector('[data-status]')?.dataset.status.includes(status)));}
  function openModal(title,body){const layer=document.createElement('div');layer.className='modal-backdrop';layer.innerHTML=`<section class="modal" role="dialog" aria-modal="true"><div class="modal-header"><h2>${title}</h2><button class="icon-button" data-close-modal aria-label="Fechar">×</button></div>${body}</section>`;document.body.append(layer);layer.addEventListener('click',e=>{if(e.target===layer||e.target.closest('[data-close-modal]'))layer.remove();});}
  async function uploadFile(file,entityType,entityId){if(!file)return;const fd=new FormData();fd.append('file',file);fd.append('entity_type',entityType);fd.append('entity_id',entityId);await api(`/api/attachments?unit_id=${state.unit.id}`,{method:'POST',body:fd});}

  document.addEventListener('click',async e=>{
    const run=e.target.closest('[data-run-report]');
    if(run){const form=$('#saved-report-form');if(!form)return;const data=Object.fromEntries(new FormData(form).entries());try{run.disabled=true;run.textContent='Consultando...';await executeReport(data.report_type,data);}catch(err){toast(err.message,true);}finally{run.disabled=false;run.textContent='Executar relatório';}return;}
    const saved=e.target.closest('[data-run-saved-report]');
    if(saved){try{const reports=await api(`/api/reports/saved?unit_id=${state.unit.id}`);const report=reports.find(x=>x.id===saved.dataset.runSavedReport);if(!report)throw new Error('Configuração não encontrada.');setPage('reports');await render();const form=$('#saved-report-form');form.elements.report_type.value=report.report_type;for(const key of ['from','to','search','status'])form.elements[key].value=report.filters?.[key]||'';await executeReport(report.report_type,report.filters||{});}catch(err){toast(err.message,true);}return;}
    const nav=e.target.closest('[data-page]');if(nav){setPage(nav.dataset.page);return;}
    const pageLink=e.target.closest('[data-page-link]');if(pageLink){setPage(pageLink.dataset.pageLink);return;}
    const action=e.target.closest('[data-action]');if(!action)return;
    try{
      if(action.dataset.action==='go-sales'){setPage('sales');return;}if(action.dataset.action==='go-expenses'){setPage('expenses');return;}
      if(action.dataset.action==='new-product'){openModal('Cadastrar produto',`<form id="product-form" class="form-grid"><label class="form-span-2">Nome<input name="name" required></label><label>SKU/código<input name="sku"></label><label>Unidade-base<input name="base_unit" value="unidade"></label><label>Estoque mínimo<input name="minimum_quantity" inputmode="decimal" value="0"></label><div class="form-actions"><button class="button primary">Salvar produto</button></div></form>`);return;}
      if(action.dataset.action==='view-lots'){const lots=await api(`/api/products/${action.dataset.id}/lots?unit_id=${state.unit.id}`);const rows=lots.map(l=>{const expired=l.expires_on&&l.expires_on<today(),soon=l.expires_on&&l.expires_on<=new Date(Date.now()+7*86400000).toISOString().slice(0,10);return `<tr><td>${esc(l.lot_code||'—')}</td><td>${esc(l.supplier||'—')}</td><td>${dateBR(l.received_on)}</td><td>${dateBR(l.expires_on)}<div>${l.expires_on?badge(expired?'Vencido':soon?'Vence em breve':'Dentro do prazo',expired?'red':soon?'amber':'green'):badge('Sem validade','gray')}</div></td><td class="money">${Number(l.quantity_remaining).toLocaleString('pt-BR',{maximumFractionDigits:3})}</td><td>${brl(l.unit_cost_cents)}</td><td>${esc(l.source_document||'—')}</td></tr>`;}).join('')||rowEmpty(7,'Nenhum lote recebido.');openModal(`Lotes · ${esc(action.dataset.name)}`,table(['Lote','Fornecedor','Recebido','Validade','Saldo','Custo unitário','Documento'],rows));return;}
      if(action.dataset.action==='receive-product'){const cats=await categories();openModal(`Receber lote · ${esc(action.dataset.name)}`,`<form id="lot-form" data-product-id="${esc(action.dataset.id)}" class="form-grid"><label>Quantidade<input name="quantity" inputmode="decimal" required></label><label>Unidade<input name="unit" value="unidade"></label><label>Data de recebimento<input name="received_on" type="date" value="${today()}" required></label><label>Validade<input name="expires_on" type="date"><span class="hint">Deixe vazio se não houver informação.</span></label><label>Fornecedor<input name="supplier"></label><label>Custo unitário (R$)<input name="unit_cost" inputmode="decimal" value="0,00"></label><label>Lote<input name="lot_code"></label><label>Nota/documento<input name="source_document"></label><div class="form-actions"><button class="button primary">Registrar lote</button></div></form>`);return;}
      if(action.dataset.action==='move-product'){openModal(`Registrar saída · ${esc(action.dataset.name)}`,`<form id="stock-move-form" data-product-id="${esc(action.dataset.id)}" class="form-grid"><label>Tipo<select name="movement_type"><option value="consumption">Consumo</option><option value="waste">Perda</option><option value="courtesy">Cortesia</option><option value="outbound">Outra saída</option><option value="adjustment">Ajuste de inventário</option></select></label><label>Quantidade<input name="quantity" inputmode="decimal" required></label><label>Direção do ajuste<select name="adjustment_direction"><option value="decrease">Reduzir saldo</option><option value="increase">Aumentar saldo</option></select><span class="hint">Usada somente em ajuste de inventário.</span></label><label>Motivo<input name="reason" required maxlength="300"></label><label class="form-span-2">Referência opcional<input name="reference"></label><div class="form-actions"><button class="button primary">Registrar movimentação</button></div></form>`);return;}
      if(action.dataset.action==='pay-expense'){const installments=Number(action.dataset.count||1);openModal(`Registrar pagamento · ${esc(action.dataset.supplier)}`,`<form id="payment-form" data-expense-id="${esc(action.dataset.id)}" class="form-grid"><label>Valor pago (R$)<input name="amount" inputmode="decimal" required></label><label>Parcela<select name="installment_number">${Array.from({length:installments},(_,i)=>`<option value="${i+1}">${i+1}ª parcela</option>`).join('')}</select></label><label>Data do pagamento<input name="paid_on" type="date" value="${today()}" required></label><label>Forma de pagamento<select name="payment_method"><option>Dinheiro</option><option>Pix</option><option>Débito</option><option>Crédito</option><option>Boleto</option><option>Transferência</option></select></label><label>Responsável<input name="responsible" value="${esc(state.user.name)}" required></label><label class="checkbox-line"><input name="paid_from_store" type="checkbox">Saiu do caixa reservado da loja</label><label class="form-span-2">Justificativa (opcional)<input name="reason"></label><p class="help-text form-span-2">Somente pagamentos marcados como caixa da loja entram no livro do caixa. Todos permanecem vinculados à despesa na DRE por competência.</p><div class="form-actions"><button class="button primary">Confirmar pagamento</button></div></form>`);return;}
    }catch(err){toast(err.message,true);}
  });

  document.addEventListener('submit',async e=>{
    const form=e.target;if(!form.matches('form'))return;e.preventDefault();const fd=new FormData(form);const data=Object.fromEntries(fd.entries());const file=data.attachment;delete data.attachment;const button=form.querySelector('button[type="submit"],button:not([type])');if(button){button.disabled=true;button.textContent='Salvando...';}
    try{
      if(form.id==='login-form'){state.csrf='';await getCsrf();const out=await post('/api/auth/login',data);state.user=out.user;state.csrf=out.csrf;if(out.user.mustChangePassword){showPasswordChange();return;}await initializeSession();toast('Acesso realizado.');return;}
      else if(form.id==='password-change-form'){if(data.new_password!==data.confirm_password)throw new Error('A confirmação da nova senha não confere.');const out=await post('/api/auth/change-password',data);state.user=out.user;state.csrf=out.csrf;document.getElementById('password-change-screen').hidden=true;await initializeSession();toast('Senha atualizada. Bem-vindo ao sistema.');return;}
      if(form.id==='sale-form'){const row=await post(`/api/sales?unit_id=${state.unit.id}`,data);if(file?.size)await uploadFile(file,'sale',row.id);toast('Faturamento salvo.');await renderSales();}
      else if(form.id==='expense-form'){const row=await post(`/api/expenses?unit_id=${state.unit.id}`,data);if(file?.size)await uploadFile(file,'expense',row.id);toast('Despesa registrada.');await renderExpenses();}
      else if(form.id==='product-form'){await post(`/api/products?unit_id=${state.unit.id}`,data);$('#page-content .modal-backdrop')?.remove();toast('Produto cadastrado.');await renderInventory();}
      else if(form.id==='lot-form'){await post(`/api/products/${form.dataset.productId}/lots?unit_id=${state.unit.id}`,data);form.closest('.modal-backdrop').remove();toast('Lote recebido.');await renderInventory();}
      else if(form.id==='stock-move-form'){await post(`/api/stock/movements?unit_id=${state.unit.id}`,{...data,product_id:form.dataset.productId});form.closest('.modal-backdrop').remove();toast('Movimentação registrada.');await renderInventory();}
      else if(form.id==='cash-open-form'){await post(`/api/cash/open?unit_id=${state.unit.id}`,data);toast('Caixa aberto.');await renderCash();}
      else if(form.id==='cash-movement-form'){await post(`/api/cash/movements?unit_id=${state.unit.id}`,data);toast('Movimento lançado.');await renderCash();}
      else if(form.id==='cash-close-form'){const result=await post(`/api/cash/close?unit_id=${state.unit.id}`,data);form.closest('.modal-backdrop')?.remove();toast(`Caixa fechado. Diferença: ${brl(result.difference_cents)}.`);await renderCash();}
      else if(form.id==='payment-form'){const row=await post(`/api/expenses/${form.dataset.expenseId}/payments?unit_id=${state.unit.id}`,data);form.closest('.modal-backdrop').remove();toast(row.status==='paid'?'Despesa quitada.':'Pagamento parcial registrado.');await renderExpenses();}
      else if(form.id==='saved-report-form'){const reportType=data.report_type;if(!data.name?.trim())throw new Error('Informe um nome para salvar a configuração.');const filters={from:data.from||null,to:data.to||null,search:data.search||'',status:data.status||''};await post(`/api/reports/saved?unit_id=${state.unit.id}`,{name:data.name,report_type:reportType,filters});toast('Configuração salva; execute-a para consultar os dados.');await renderReports();}
      else if(form.id==='user-form'){await post(`/api/admin/users?unit_id=${state.unit.id}`,data);toast('Usuário criado.');await renderUsers();}
      else if(form.id==='target-form'){await post(`/api/settings?unit_id=${state.unit.id}`,data);toast('Meta atualizada com nova vigência.');await renderSettings();}
      else if(form.id==='category-form'){await post(`/api/categories?unit_id=${state.unit.id}`,data);toast('Categoria criada.');await renderSettings();}
      else if(form.id==='import-form'){const fd2=new FormData(form);const preview=await api(`/api/import/preview?unit_id=${state.unit.id}`,{method:'POST',body:fd2});showImportMapping(preview);toast('Prévia pronta. Confira o mapeamento antes de confirmar.');}
      else if(form.id==='import-commit-form'){const map={};$$('[data-map-target]',form).forEach(s=>map[s.dataset.mapTarget]=s.value);const result=await post(`/api/import/${form.dataset.batchId}/commit?unit_id=${state.unit.id}`,{mapping:map});$('#import-preview').innerHTML=`<section class="card section-card"><h2>Resultado da importação</h2><div class="mini-kpis"><div class="mini-kpi">Linhas <strong>${result.total}</strong></div><div class="mini-kpi">Importadas <strong>${result.imported}</strong></div><div class="mini-kpi">Rejeitadas <strong>${result.rejected.length}</strong></div></div>${result.rejected.length?table(['Linha','Motivo'],result.rejected.map(x=>`<tr><td>${x.line}</td><td>${esc(x.message)}</td></tr>`).join('')):''}</section>`;toast(`Importação concluída: ${result.imported} linha(s).`);}
      else if(form.id==='payment-modal-form'){/* reserved */}
    }catch(err){toast(err.message,true);const errNode=form.querySelector('.form-error');if(errNode)errNode.textContent=err.message;}
    finally{if(button){button.disabled=false;if(button.textContent==='Salvando...')button.textContent='Salvar';}}
  });

  function showImportMapping(p){const fields={sales:[['sale_date','Data do faturamento'],['amount','Faturamento'],['channel','Canal'],['target','Meta'],['notes','Observações']],expenses:[['supplier','Fornecedor'],['document_number','Nº documento'],['issue_date','Emissão'],['due_date','Vencimento'],['description','Descrição'],['total','Valor total']],products:[['name','Nome do produto'],['sku','SKU'],['unit','Unidade']]};const options=p.headers.map(h=>`<option value="${esc(h)}">${esc(h)}</option>`).join('');const mapping=fields[p.kind].map(([key,label])=>`<label class="mapping-item">${label}<select data-map-target="${key}"><option value="">— não mapear —</option>${options}</select></label>`).join('');const sample=p.rows.slice(0,5).map(row=>`<tr>${p.headers.slice(0,5).map(h=>`<td>${esc(row[h]??'')}</td>`).join('')}</tr>`).join('')||rowEmpty(1,'Sem linhas.');$('#import-preview').innerHTML=`<section class="card form-card"><div class="section-head"><div><h2>2 · Mapear colunas</h2><p>${esc(p.source_name)} · aba ${esc(p.sheet)} · ${p.total_rows} linha(s)</p></div><span class="badge amber">Prévia · ainda não importado</span></div><form id="import-commit-form" data-batch-id="${esc(p.id)}"><div class="mapping-grid">${mapping}</div><div class="form-actions"><button class="button primary">Confirmar importação</button></div></form></section><section class="card table-card"><div class="table-toolbar"><h2>3 · Conferir amostra (até 5 linhas)</h2></div>${table(p.headers.slice(0,5),sample)}</section>`;}

  document.addEventListener('click',e=>{if(e.target.id==='logout-button'||e.target.id==='mobile-logout'){post('/api/auth/logout',{}).finally(()=>{state.user=null;state.csrf='';showLogin();});}if(e.target.id==='menu-toggle')$('#sidebar').classList.toggle('open');});
  async function initializeSession(){try{const me=await api('/api/auth/me');state.user=me.user;state.csrf=me.csrf;if(me.user.mustChangePassword){showPasswordChange();return;}state.units=me.units;state.unit=me.units[0];showApp();setPage('overview');}catch(e){showLogin();}}
  async function start(){try{await getCsrf();await initializeSession();}catch{showLogin();}}
  start();
})();
